Lang["Q2_2241"] = "Take Jannok's Rose to Syurna in Darnassus."
Lang["Q2_2242"] = "Find Sethir the Ancient and bring back any clues that you may discover to Syurna."
Lang["Q2_2258"] = "대머리수리 모이주머니 5개, 바위코요테 송곳니 10개, 바위 정령 파편 5개를 카르가스에 있는 자칼 모스멜드에게 가져가야 합니다."
Lang["Q2_2259"] = "Contact Erion Shadewhisper in Darnassus."
Lang["Q2_2260"] = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\""
Lang["Q2_2278"] = "바위감시자와 대화하고 그가 알고 있는 고대의 지식을 배우십시오. 지식을 배운 후에는 노르간논의 원반을 가동하십시오."
Lang["Q2_2279"] = "아이언포지에 있는 탐험가 연맹에 노르간논의 소형 백금 원반을 가져가야 합니다."
Lang["Q2_2280"] = "썬더 블러프에 있는 현자 중 하나에게 노르간논의 소형 원반을 가져가야 합니다."
Lang["Q2_2281"] = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius."
Lang["Q2_2282"] = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire."
Lang["Q2_2283"] = "울다만 발굴 현장에서 값진 목걸이를 찾아 오그리마에 있는 드란 드로퍼스에게 가져다주어야 합니다. 목걸이는 파손된 것이라도 괜찮습니다."
Lang["Q2_2284"] = "울다만 깊은 곳에서 보석의 행방에 대한 단서를 찾아야 합니다."
Lang["Q2_2298"] = "Travel to Stormwind and seek out Renzik \"The Shiv.\""
Lang["Q2_2299"] = "Travel to Ironforge and speak with Hulfdan Blackbeard."
Lang["Q2_2300"] = "Travel to Stormwind and seek out Renzik \"The Shiv.\""
Lang["Q2_2318"] = "성기사의 일지를 번역할 수 있는 사람을 찾아야 합니다. 가장 가까운 곳은 황야의 땅의 카르가스입니다."
Lang["Q2_2339"] = "울다만에서 목걸이에 필요한 보석 3개와 마력원천을 회수한 후 카르가스에 있는 자칼 모스멜드에게 가져다주어야 합니다. 자칼의 말에 의하면 울다만에서 가장 강한 피조물을 처치하면 마력원천을 얻을 수 있다고 합니다."
Lang["Q2_2342"] = "울다만의 남쪽 대전당에 있는 궤짝에서 가레트가의 보물을 찾아 언더시티에 있는 그에게 가져가야 합니다."
Lang["Q2_2359"] = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower."
Lang["Q2_2360"] = "Travel to Westfall and find Agent Kearnen for your debriefing."
Lang["Q2_2378"] = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow."
Lang["Q2_2379"] = "Speak with Zando'zan at the Cleft of Shadow."
Lang["Q2_2380"] = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar."
Lang["Q2_2381"] = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.\n\nShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!"
Lang["Q2_2382"] = "Travel to Ratchet and speak with Wrenix the Wretched."
Lang["Q2_2383"] = "Read the Simple Parchment and speak to Frang in the Valley of Trials."
Lang["Q2_2398"] = "울다만에서 밸로그를 찾아야 합니다."
Lang["Q2_2418"] = "황야의 땅에 있는 리글퍼즈에게 덴트리움 마법석 8개와 안알레움 마법석 8개를 가져가야 합니다."
Lang["Q2_2458"] = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\n\nWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\n\nThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize."
Lang["Q2_2460"] = "Perform the Shattered Salute on Shenthul."
Lang["Q2_2478"] = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.\n\nAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction."
Lang["Q2_2479"] = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\n\nTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!"
Lang["Q2_2480"] = "Wait for Serge Hinott to complete the cure."
Lang["Q2_2500"] = "대머리수리 모이주머니 5개, 바위코요테 송곳니 10개, 바위 정령 파편 5개를 텔사마에 있는 가크 힐터치에게 가져가야 합니다."
Lang["Q2_26"] = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."
Lang["Q2_2607"] = "Speak with Doc Mixilpixil in the cellar of the Barracks."
Lang["Q2_2608"] = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?"
Lang["Q2_2609"] = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young  fella:lady;."
Lang["Q2_261"] = "언데드 약탈자 30마리를 처치한 후 나이젤의 야영지에 있는 수사 안톤에게 돌아가야 합니다."
Lang["Q2_27"] = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."
Lang["Q2_272"] = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade."
