Lang["Q2_6122"] = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\n\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore."
Lang["Q2_6123"] = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve."
Lang["Q2_6124"] = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them.  Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins."
Lang["Q2_6125"] = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_6126"] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_6127"] = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\n\nDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens."
Lang["Q2_6128"] = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve."
Lang["Q2_6129"] = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them.  Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads."
Lang["Q2_6130"] = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff."
Lang["Q2_6133"] = "동부 역병지대의 북쪽 경계로 이동하여 쿠엘탈라스 기록부를 입수해야 합니다. 기록부는 쿠엘리시엔 오두막 어딘가에 있습니다. 순찰자 8명, 길잡이 8명, 수렵꾼 8명을 처치해야 합니다."
Lang["Q2_6135"] = "Find Duskwing north of the Marris Stead and slay him. Recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller."
Lang["Q2_6136"] = "동부 역병지대 북부 불모지에서 피고름구더기를 찾아 물리친 후 나타노스 블라이트콜러에게 가야 합니다."
Lang["Q2_6141"] = "잊혀진 땅에 있는 수사 안톤과 대화해야 합니다."
Lang["Q2_6144"] = "언더시티로 가서 바리마트라스와 대화해야 합니다."
Lang["Q2_6163"] = "스트라솔름으로 가서 먹보 람스타인을 처치하고 그 증거로 그의 머리카락을 나타노스에게 가져가야 합니다."
Lang["Q2_63"] = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest."
Lang["Q2_65"] = "그라이언 스타우트맨틀이 레이크샤이어의 와일리와 대화하라고 부탁했습니다."
Lang["Q2_6521"] = "사절 말킨을 처치한 다음 언더시티에 있는 바리마트라스에게 그의 머리카락을 증거로 가져가야 합니다."
Lang["Q2_6522"] = "작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다."
Lang["Q2_65593"] = "Bring the hearts of Avelina Lilly and Isaac Pearson to Carendin Halgar in the Temple of the Damned."
Lang["Q2_65597"] = "Using the Lovers' Hearts, summon and subdue an incubus, then return the Lovers' Hearts to Carendin Halgar in the Magic Quarter of the Undercity."
Lang["Q2_65601"] = "오그리마에 있는 마가르와 대화하십시오."
Lang["Q2_65602"] = "목재 조각상을 찾아 스톰윈드의 마법사 지구에 있는 대흑마법사 게이킨에게 가져가야 합니다."
Lang["Q2_65603"] = "목재 조각상을 사용하여 인큐버스를 소환해 제압한 후, 어둠의 희생양 선술집에 있는 대흑마법사 게이킨에게 목재 조각상을 가져가야 합니다."
Lang["Q2_65604"] = "Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar."
Lang["Q2_6561"] = "황혼의 군주 켈리스를 처치하고 그 증거로 그의 머리카락을 썬더 블러프에 있는 바샤나 룬토템에게 가져가야 합니다."
Lang["Q2_65610"] = "잿빛 골짜기에 있는 유성 호수를 조사한 후 오그리마에 있는 간룰 블러드아이에게 보고해야 합니다."
Lang["Q2_6562"] = "잿빛 골짜기에 있는 제네우 생크리와 대화하십시오."
Lang["Q2_6563"] = "잿빛 골짜기에 있는 제네우 생크리에게 아쿠마이의 사파이어 20개를 가져가야 합니다."
Lang["Q2_6564"] = "축축한 메모를 잿빛 골짜기의 제네우 생크리에게 가져가십시오."
Lang["Q2_6565"] = "검은심연의 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오."
Lang["Q2_6626"] = "가시덩굴일족 전투호위병과 가시덩굴일족 가시마술사, 그리고 죽음의 머리교 신도를 각각 8마리씩 죽인 후 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어에게 돌아가야 합니다."
Lang["Q2_6627"] = "브라우그 딤스피릿의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 브라우그 딤스피릿은 돌발톱 산맥에 있을 것입니다."
Lang["Q2_6628"] = "파쿠알 핀탈라스의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 파쿠알 핀탈라스는 언더시티에 있을 것입니다."
Lang["Q2_6681"] = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\n\nYour cunning will be tested along the way. Be prepared."
Lang["Q2_6701"] = "Syndicate Emblems"
Lang["Q2_6921"] = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다."
Lang["Q2_6922"] = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다."
Lang["Q2_6981"] = "톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오."
Lang["Q2_7028"] = "트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다."
Lang["Q2_7029"] = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다."
Lang["Q2_7041"] = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다."
Lang["Q2_7044"] = "셀레브라스의 홀 조각인 셀레브리안 마법봉과 셀레브리안 다이아몬드를 찾아야 합니다."
Lang["Q2_7046"] = "회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다."
Lang["Q2_7064"] = "공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다."
Lang["Q2_7065"] = "공주 테라드라스를 해치우고 잊혀진 땅의 나이젤의 야영지에 있는 수호자 마란디스를 찾아가야 합니다."
Lang["Q2_7066"] = "달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다."
Lang["Q2_7067"] = "추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다."
Lang["Q2_7068"] = "마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다."
Lang["Q2_7070"] = "마라우돈에서 음영석 조각 10개를 모아서 먼지진흙 습지대의 해안에 위치한 테라모어에 있는 대마법사 테르보쉬에게 가져가야 합니다."
Lang["Q2_709"] = "실성한 텔두린에게 류네의 서판을 가져가야 합니다."
Lang["Q2_720"] = "발굴조사단장 라이돌에게 해머토 그레즈가 살아 있다는 소식을 전해야 합니다."
Lang["Q2_7201"] = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals."
Lang["Q2_721"] = "울다만에서 해머토 그레즈를 찾아야 합니다."
Lang["Q2_722"] = "해머토의 아뮬렛을 찾아 울다만에 있는 해머토에게 가져가야 합니다."
Lang["Q2_7441"] = "혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다."
Lang["Q2_7461"] = "이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다."
Lang["Q2_7462"] = "도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!"
Lang["Q2_7481"] = "혈투의 전장을 뒤져 카리엘 윈탈루스를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다."
Lang["Q2_7482"] = "혈투의 전장을 뒤져 카리엘 윈탈루스를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 페더문 요새에 있는 학자 룬쏜에게 돌아가야 합니다."
Lang["Q2_7488"] = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어에게 레스텐드리스의 그물을 가져가야 합니다."
Lang["Q2_7489"] = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다."
Lang["Q2_7492"] = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프와 대화해야 합니다."
Lang["Q2_7494"] = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어와 대화해야 합니다."
Lang["Q2_7499"] = "Return the book to its rightful owners."
Lang["Q2_7506"] = "Return the book to its rightful owners."
Lang["Q2_7562"] = "불타는 평원에 있는 모르줄 블러드브링어와 대화하십시오."
Lang["Q2_7563"] = "불타는 평원에 있는 모르줄 블러드브링어에게 흉포한 올빼미야수의 피 30병을 가져가야 합니다."
Lang["Q2_7564"] = "불타는 평원에 있는 고르지키 와일드아이즈에게 피가 담긴 상자를 가져가야 합니다."
Lang["Q2_7581"] = "페랄라스에 있는 혈투의 전장으로 간 다음 굽이나무 지구에 서식하는 야생혈족 사티르로부터 사티르의 피 15개를 회수한 후 타락의 흉터에 있는 다이오에게 돌아가야 합니다."
Lang["Q2_7582"] = "여명의 설원에 있는 검은속삭임 협곡에서 서식하는 헤더린의 악마들로부터 헤더린의 눈물 5개를 빼앗아야 합니다. 임무를 완수하면 타락의 흉터에 있는 다이오에게 돌아가십시오."
Lang["Q2_7583"] = "타락의 흉터에서 파멸의수호병을 찾아내십시오.\n\n빛나는 수정 감옥을 파멸의수호병에게 사용해야 합니다. 악마는 잡히지 않으려고 맹렬하게 공격할 테니 정신을 바짝 차리십시오.\n\n성공하면 사로잡은 파멸의수호병을 타락의 흉터에 있는 다이오에게 데려가야 합니다."
Lang["Q2_7601"] = "악령의 숲에 있는 임프시와 대화하십시오."
Lang["Q2_7602"] = "악령의 숲에 있는 임프시가 이 세계의 각기 다른 세 개의 지역에서 완전무결한 지옥의 정수 3개를 가져와 달라고 부탁했습니다.\n\n아즈샤라에는 레가쉬 사티로스들, 자에데나르에는 자에데나르 부대원들, 그리고 저주받은 땅에서는 지옥군단병 보초들이 각기 그 지역의 완전무결한 지옥의 정수를 갖고 있습니다.\n\n완전무결한 지옥의 정수 3개를 다 모은 다음에는 악령의 숲에 있는 임프시에게 돌아가야 합니다."
Lang["Q2_7603"] = "악령의 숲에 있는 불벼락 골짜기를 수색해 크로쉬우스의 잔해를 찾아야 합니다. 찾으면 부근에서 지옥의 불꽃을 사용해 크로쉬우스를 되살리십시오. 크로쉬우스가 깨어나면 놈을 쓰러뜨린 후 크로쉬우스의 지옥핵을 꺼내야 합니다.\n\n크로쉬우스의 지옥핵을 악령의 숲에 있는 전지전능한 나이비에게 가져다주십시오."
Lang["Q2_7621"] = "A Warning"
Lang["Q2_7622"] = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain."
Lang["Q2_7623"] = "불타는 평원에 있는 고르지키에게서 어둠의 물약을 구입해야 합니다.\n\n이 물약을 사용하여 자에데나르로 가서 군주 베인할로우와 대화하십시오."
Lang["Q2_7624"] = "울라텍과 맞서 싸운 후 자에데나르에 있는 베인할로우 군주에게 배신자의 증거를 가져가야 합니다."
Lang["Q2_7625"] = "우르단에게서 소로시안 별가루를 구입한 후, 불타는 평원에 있는 고르지키 와일드아이즈에게 가져가야 합니다."
Lang["Q2_7626"] = "불타는 평원에 있는 고르지키 와일드아이즈에게 암흑 강화의 비약 10개를 가져가야 합니다."
Lang["Q2_7627"] = "불타는 평원에 있는 고르지키 와일드아이즈에게 눈부신 큰 결정 6개와 검은무쇠 광석 25개를 가져가야 합니다."
Lang["Q2_7628"] = "불타는 평원에 있는 고르지키 와일드아이즈에게 검은용 비늘 35개를 가져가야 합니다."
Lang["Q2_7629"] = "단지 안에 든 임프를 스칼로맨스에 있는 연금술 실험대로 가져가야 합니다. 양피지가 완성되면 단지를 고르지키 와일드아이즈에게 되돌려 주십시오."
Lang["Q2_7630"] = "불타는 평원에 있는 고르지키에게 아케이나이트 주괴 3개를 가져가야 합니다."
Lang["Q2_7631"] = "모르줄의 지시서를 잘 읽으십시오. 소로시안 공포마를 소환해 물리친 후 그 영혼을 결속시켜야 합니다."
Lang["Q2_7632"] = "Find the owner of the Ancient Petrified Leaf. Good luck, you; It's a big world."
Lang["Q2_7633"] = "An Introduction"
Lang["Q2_7634"] = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood."
Lang["Q2_7635"] = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood."
Lang["Q2_7636"] = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself."
Lang["Q2_7637"] = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer.  You will need to make a donation of 150 gold in order to secure it."
Lang["Q2_7638"] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."
Lang["Q2_7639"] = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7640"] = "Use the Exorcism Censer to drive out the spirits that torment Terrordale.  When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7641"] = "Speak with Grimand Elmore in Stormwind's Dwarven District."
Lang["Q2_7642"] = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."
Lang["Q2_7643"] = "Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.\n\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it."
Lang["Q2_7644"] = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7645"] = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills.  The Argent Dawn is known as the sole purveyor of the biscuits.\n\nYou also need to give her 50 gold to soothe her ruffled sensibilities."
Lang["Q2_7646"] = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7647"] = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."
Lang["Q2_7648"] = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection."
Lang["Q2_7666"] = "Again Into the Great Ossuary"
Lang["Q2_7667"] = "If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond."
Lang["Q2_7668"] = "The Darkreaver Menace"
Lang["Q2_7669"] = "Again Into the Great Ossuary"
Lang["Q2_7670"] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."
Lang["Q2_79007"] = "불모의 땅 46, 73으로 이동하세요. 타버린 잔해와 상호작용하여 퀘스트를 수락하세요.\n\n서부 몰락지대 37, 50에서 못 박힌 판자와 상호작용해 퀘스트를 완료하세요. 떠나기 전에 그 판자에서 디딤돌을 수락하세요."
Lang["Q2_79008"] = "서부 몰락지대 37, 50으로 이동하세요. 못 박힌 판자 옆의 타버린 잔해와 상호작용하여 퀘스트를 수락하세요.\n\n불모의 땅 46, 73의 타버린 잔해에서 퀘스트를 완료한 뒤, 그곳의 못 박힌 판자와 상호작용하여 디딤돌을 수락하세요."
Lang["Q2_79192"] = "호드는 서부 몰락지대 37, 50의 못 박힌 판자에서 이 퀘스트를 받습니다. 얼라이언스는 불모의 땅 46, 73의 못 박힌 판자에서 받습니다.\n\n돌발톱 산맥 51, 51로 이동하세요. 길에서 산 속의 틈을 따라 야영지에 도착할 때까지 가세요. 주머니 잡동사니(40.8, 52.5)와 상호작용하세요."
Lang["Q2_79974"] = "돌발톱 산맥의 흙무더기(39.6, 49.9)와 상호작용하여 이 퀘스트를 수락하세요.\n\n모단 호수 49, 12의 댐으로 이동하세요. 절벽으로 뛰어내린 뒤 조각된 작은 입상(49.5, 12.8)과 상호작용하세요."
Lang["Q2_79975"] = "모단 호수 댐의 조각된 작은 입상(49.5, 12.8)과 상호작용하여 이 퀘스트를 수락하세요.\n\n힐스브래드 구릉지 81, 56으로 이동하세요. 아라시 고원으로 향하는 문을 바라본 채 왼쪽으로 돌아 쓰러진 수레에 닿을 때까지 벽을 따라가세요. 점프 퍼즐을 따라 야영지로 간 뒤 전령 가방(아라시 고원 22.4, 24.2)과 상호작용하세요."
Lang["Q2_79976"] = "전령 가방과 상호작용한 다음, 바로 아래에 있는 급히 말아 둔 가방과 상호작용하여 아늑한 침낭을 받으세요."
Lang["Q2_79980"] = "돌발톱 야영지에서 주머니 잡동사니(40.8, 52.5)와 상호작용하여 이 퀘스트를 수락하세요.\n\n야영지를 가로질러 산 아래로 뛰어내린 뒤, 흙무더기(39.6, 49.9)가 있는 절벽으로 가서 상호작용하세요."
Lang["Q2_79987"] = "반지를 지니고 있어도 되고, 반지 안쪽에 인장과 각인을 남긴 사람을 찾아도 됩니다."
